class Commissioning(NetactBase):
    """Commisioning"""

    def __init__(self):
        super(Commissioning, self).__init__()

    def configuration_manage(self, **kwargs):
        """Configure Manage"""
        plan = None
        delete_plan = kwargs.pop('delete_plan', True)
        should_provision = kwargs.pop('should_provision', True)
        # This is not required for netact. Hence popping operations from argument,
        # otherwise we might see failure if user passes Operation from testcase
        kwargs.pop('operation') if kwargs.get('operation') else ''
        bts_moc_id = kwargs.get("bts_moc_id", self.bts_moc_id)

        try:
            alias = kwargs.get('alias', 'default')
            # self.netact_factory.cm_operations.upload_configuration_data(dist_names=self.bts_moc_id, alias=alias)

            self.netact_factory.netact.upload_configuration(dist_names=bts_moc_id, alias=alias)
            # plan = self.plan_create(**kwargs)
            plan = self.plan(operation='create', **kwargs)
            self._add_mocs_params_to_plan(plan, **kwargs)
            if should_provision:
                self.provision_plan(**kwargs)
        except Exception as err:
            logger.debug(traceback.print_exc())
            raise err
        finally:
            if delete_plan and plan is not None:
                self.plan(operation='delete', **kwargs)
                # self.plan_delete(**kwargs)

    def configuration_get(self, **kwargs):
        """Get configuration"""
        distname = kwargs.get('dist_name', self.bts_moc_id)
        timeout = kwargs.get('timeout', 7200)
        alias = kwargs.get('alias', 'default')
        # self.netact_factory.cm_operations.upload_configuration_data(dist_names=distname, alias=alias, timeout=timeout)
        self.netact_factory.netact.upload_configuration(dist_names=distname, alias=alias, timeout=timeout)
        # actual = self.netact_factory.cm_editor.get_actual(alias)
        # managed_obj = self.netact_factory.cm_editor.get_managed_object(actual, distname, alias)
        actual = self.netact_factory.netact.get_actual_configuration(alias=alias)
        managed_obj = self.netact_factory.netact.get_managed_object(configuration=actual, mo_id=distname, alias=alias)
        return managed_obj.parameters

    def _get_meta_params(self, actual, moc_details, alias):
        dist_name = ''
        meta_class = ''
        meta_version = ''
        operation = moc_details['operation']
        if operation.upper() == 'CREATE':
            if 'meta_params' in list(moc_details.keys()):
                meta_class = moc_details['meta_params']['meta_class']
                meta_version = moc_details['meta_params']['meta_version']
            elif 'existing_moc_dn' in list(moc_details.keys()):
                existing_moc_dn = moc_details['existing_moc_dn']
                # existing_moc = self.netact_factory.cm_editor.get_managed_object(actual, existing_moc_dn, alias=alias)
                existing_moc = self.netact_factory.netact.get_managed_object(configuration=actual,
                                                                             mo_id=existing_moc_dn, alias=alias)
                meta_class = existing_moc.meta_class
                meta_version = existing_moc.meta_version
            else:
                raise Exception("Either 'meta_params' or 'existing_moc_dn' param mandatory in given delta")
            dist_name = moc_details['dist_name']
        elif operation.upper() == 'UPDATE' or operation.upper() == 'DELETE':
            dist_name = moc_details['existing_moc_dn']
            # existing_moc = self.netact_factory.cm_editor.get_managed_object(actual, dist_name, alias=alias)
            existing_moc = self.netact_factory.netact.get_managed_object(configuration=actual, mo_id=dist_name,
                                                                         alias=alias)
            meta_class = existing_moc.meta_class
            meta_version = existing_moc.meta_version
        return dist_name, meta_class, meta_version

    def provision_plan(self, **kwargs):
        """Provision plan"""
        plan_name = kwargs.get('plan_name', 'iv_fw_plan')
        dist_names = kwargs.get('dist_names', self.bts_moc_id)
        backup_plan_name = kwargs.get('backup_plan_name')
        create_backup_plan = kwargs.get('create_backup_plan', False)
        provisioning_operation = kwargs.get('provisioning_operation', 'activate')
        # validate = kwargs.get('validate', True)
        ignore_errors = kwargs.get('ignore_errors', False)
        timeout = kwargs.get('timeout', 7200)
        alias = kwargs.get('alias', 'default')
        # return self.netact_factory.cm_operations.provision_plan(plan_name=plan_name,
        #                                                         provisioning_operation='activate', validate=True,
        #                                                         ignore_errors=False, timeout=timeout, alias=alias)
        # return self.netact_factory.cm_operations.provision_plan(plan_name=plan_name, dist_names=dist_names,
        #                                                         backup_plan_name=backup_plan_name,
        #                                                         create_backup_plan=create_backup_plan,
        #                                                         provisioning_operation=provisioning_operation,
        #                                                         validate=validate, ignore_errors=ignore_errors,
        #                                                         timeout=timeout, alias=alias)

        if provisioning_operation.lower() == "activate_preactivated_plan":
            parameters = kwargs.get("parameters", None)
            verbose = kwargs.get("verbose", True)
            schedule = kwargs.get("schedule", None)
            return self.netact_factory.netact.activate_preactivated_plan(plan_name, dist_names=dist_names,
                                                                         parameters=parameters, verbose=verbose,
                                                                         schedule=schedule, ignore_errors=ignore_errors,
                                                                         timeout=timeout, alias=alias)
        return self.netact_factory.netact.provision_plan(plan_name=plan_name, dist_names=dist_names,
                                                         backup_plan_name=backup_plan_name,
                                                         create_backup_plan=create_backup_plan,
                                                         provisioning_operation=provisioning_operation,
                                                         ignore_errors=ignore_errors,
                                                         timeout=timeout, alias=alias)

    def cm_upload(self, **kwargs):
        """CM upload"""
        sran_bts_hw_content_in_use = kwargs.get('sran_bts_hw_content_in_use', None)
        ignore_errors = kwargs.get('ignore_errors', False)
        dist_name = kwargs.get("dist_name", 'PLMN-PLMN/MRBTS-{bts_id}'.format(bts_id=get_config_variable(['bts_id'])))
        timeout = kwargs.get('timeout', 7200)
        alias = kwargs.get('alias', 'default')
        # return self.netact_factory.cm_operations.upload_configuration_data(
        #     dist_names=bts_moc_distname, sran_bts_hw_content_in_use=sran_bts_hw_content_in_use,
        #     ignore_errors=ignore_errors, timeout=timeout, alias=alias)
        return self.netact_factory.netact.upload_configuration(dist_names=dist_name,
                                                               parameters = {'-sranBtsHwContentInUse'
                                                                           : sran_bts_hw_content_in_use},
                                                               ignore_errors=ignore_errors,
                                                               timeout=timeout, alias=alias)

    def _add_mocs_params_to_plan(self, plan, **kwargs):
        delta_file = kwargs['config']
        alias = kwargs.get('alias', 'default')
        # actual = self.netact_factory.cm_editor.get_actual(alias=alias)
        actual = self.netact_factory.netact.get_actual_configuration(alias=alias)
        skip_autocorrection = kwargs.get('skip_autocorrection', False)
        if delta_file:
            delta_json_data = self._load_delta_file_into_dict(delta_file, skip_autocorrection)
            # for item, moc_details in list(delta_json_data.items()):
            for moc_details in delta_json_data:
                moc_dist_name, meta_class, meta_version = self._get_meta_params(actual, moc_details, alias)
                self._operate_managed_object(plan, meta_class, meta_version, moc_dist_name, moc_details, alias)

    def _load_delta_file_into_dict(self, delta_file, skip_autocorrection):
        delta_file_dir = get_config_variable(['delta_files'])
        delta_full_path = os.path.join(delta_file_dir, delta_file)
        # delta_json_data = {}
        ne_input_file = delta_full_path
        if not skip_autocorrection:
            conv_file = DeltaFileConverter()
            auto_correct = AutoCorrectionTool()
            ac_input_file = conv_file.convert_for_autocorrection(delta_full_path)
            corrected_file = auto_correct.compare_delta_against_nidd(delta_file=ac_input_file, module="netact")
            logger.debug("#### updated file {}".format(corrected_file))
            ne_input_file = conv_file.convert_for_netact(corrected_file)

        with open(ne_input_file, "r") as file_handle:
            delta_json_data = json.load(file_handle)
        logger.debug('delta_file_content:\n{}'.format(str(delta_json_data)))
        return delta_json_data

    def plan(self, **kwargs):
        """Plan"""
        operation = kwargs['operation']
        plan_name = kwargs.get('plan_name', 'iv_fw_plan')
        plan_description = kwargs.pop('plan_description', plan_name)
        alias = kwargs.get('alias', 'default')
        plan = None
        if operation.lower() == 'create':
            try:
                # plan = self.netact_factory.cm_editor.create_plan(plan_name, description=plan_description, alias=alias)
                plan = self.netact_factory.netact.create_plan_configuration(name=plan_name,
                                                                            description=plan_description,
                                                                            alias=alias)
            except Exception:  # PlanNotFound:
                # plan = self.netact_factory.cm_editor.get_plan(plan_name, alias=alias)
                plan = self.netact_factory.netact.get_plan_configuration(name=plan_name, alias=alias)
        elif operation.lower() == 'get' or operation.lower() == 'delete':
            # plan = self.netact_factory.cm_editor.get_plan(plan_name, alias=alias)
            plan = self.netact_factory.netact.get_plan_configuration(name=plan_name, alias=alias)
            if operation.lower() == 'delete':
                plan.delete()
        return plan

