    def _operate_managed_object(self, plan, meta_class, meta_version, moc_dist_name, moc_details, alias):
        operation = moc_details['operation']
        logger.debug('create_managed_object args: {} {} {} {} {}'.format(plan, meta_class, meta_version, moc_dist_name,
                                                                         operation))
        if operation.upper() == 'DELETE':
            # self.netact_factory.cm_editor.create_managed_object(plan, meta_class, meta_version, moc_dist_name,
            #                                                     operation, alias=alias)
            self.netact_factory.netact.create_managed_object(plan=plan, meta_class=meta_class,
                                                             meta_version=meta_version, mo_id=moc_dist_name,
                                                             operation=operation, alias=alias)
        else:
            param_dict = moc_details['param_dict']
            # self.netact_factory.cm_editor.create_managed_object(plan, meta_class, meta_version, moc_dist_name,
            #                                                     operation, alias=alias, **param_dict)
            self.netact_factory.netact.create_managed_object(plan=plan, meta_class=meta_class,
                                                             meta_version=meta_version,
                                                             mo_id=moc_dist_name, operation=operation, alias=alias,
                                                             **param_dict)

    def validate_plan(self, **kwargs):
        """
        The plan is validated in NetAct before pre-activation.

        :param string plan_name: Specifies a plan name.
        :param string|list(string) dist_names: Specifies the scope of the operation.
        :param bool verbose: If ``True``, returns more detailed output from executed operation.
        :param dict parameters: Parameters not parameterized at the level of method but allowed by CLI,
            e.g.::

                {
                    '-lteContentInUse': True,
                    '-sranBtsContentInUse': False
                }

        :param string schedule: ``prepare_schedule`` method should be used to obtain correct value.
        :param bool ignore_errors: If ``True``, shows warnings instead of raising errors when operation fails.
        :param int|string timeout: Timeout for executing operation.
        :param string alias: Netact instance name. Default value is ``default``.
        :return: Operation output.
        """
        plan_name = kwargs.get('plan_name', 'iv_fw_plan')
        dist_names = kwargs.get('dist_names', self.bts_moc_id)
        ignore_errors = kwargs.get('ignore_errors', False)
        timeout = kwargs.get('timeout', 7200)
        alias = kwargs.get('alias', 'default')
        parameters = kwargs.get("parameters", None)
        verbose = kwargs.get("verbose", True)
        schedule = kwargs.get("schedule", None)

        return self.netact_factory.netact.validate_plan(plan_name, dist_names=dist_names, parameters=parameters,
                                                        verbose=verbose, schedule=schedule, ignore_errors=ignore_errors,
                                                        timeout=timeout, alias=alias)

    def prevalidate_plan(self, **kwargs):
        """
        The plan is validated in NetAct before pre-activation.

        :param string plan_name: Specifies a plan name.
        :param string|list(string) dist_names: Specifies the scope of the operation.
        :param bool verbose: If ``True``, returns more detailed output from executed operation.
        :param string schedule: ``prepare_schedule`` method should be used to obtain correct value.
        :param bool ignore_errors: If ``True``, shows warnings instead of raising errors when operation fails.
        :param int|string timeout: Timeout for executing operation.
        :param string alias: Netact instance name. Default value is ``default``.
        :return: Operation output.
        """
        plan_name = kwargs.get('plan_name', 'iv_fw_plan')
        dist_names = kwargs.get('dist_names', self.bts_moc_id)
        ignore_errors = kwargs.get('ignore_errors', False)
        timeout = kwargs.get('timeout', 7200)
        alias = kwargs.get('alias', 'default')
        verbose = kwargs.get("verbose", True)
        schedule = kwargs.get("schedule", None)

        op = self.netact_factory.netact.prevalidate_plan(plan_name, dist_names=dist_names, verbose=verbose,
                                                         schedule=schedule, ignore_errors=ignore_errors,
                                                         timeout=timeout, alias=alias)

        if "successful" not in op:
            raise Exception(str(op))
        else:
            return op

